select bv.id as voucherId, l.operation_time as operationTime, l.error_message as errorMessage, l.operation_details as operationDetails from port_pilotage.billing_vouchers bv left join ( select voucher_id, max(id) as max_id from port_pilotage.invoice_operation_logs where operation_type = 'PAYMENT_NOTICE' group by voucher_id ) t on t.voucher_id = bv.id left join port_pilotage.invoice_operation_logs l on l.id = t.max_id where bv.audit_status = 'APPROVED' and bv.payment_status = 'UNPAID' and (t.max_id is null or l.result = 'FAIL')
and (bv.voucher_code like concat('%', #{keyword}, '%') or bv.invoice_number like concat('%', #{keyword}, '%'))
order by l.operation_time desc limit #{offset}, #{limit}

